dress","name":"to","type":"address"}],"name":"OwnershipTransferred","type":"event"},{"inputs":[],"name":"acceptOwnership","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"components":[{"internalType":"uint64","name":"destChainSelector","type":"uint64"},{"internalType":"contract IRouter","name":"router","type":"address"},{"internalType":"uint8","name":"addressBytesLength","type":"uint8"},{"internalType":"bool","name":"tokenReceiverAllowed","type":"bool"},{"internalType":"uint16","name":"messageNetworkFeeUSDCents","type":"uint16"},{"internalType":"uint16","name":"tokenNetworkFeeUSDCents","type":"uint16"},{"internalType":"uint32","name":"baseExecutionGasCost","type":"uint32"},{"internalType":"address[]","name":"defaultCCVs","type":"address[]"},{"internalType":"address[]","name":"laneMandatedCCVs","type":"address[]"},{"internalType":"address","name":"defaultExecutor","type":"address"},{"internalType":"bytes","name":"offRamp","type":"bytes"}],"internalType":"struct OnRamp.DestChainConfigArgs[]","name":"destChainConfigArgs","type":"tuple[]"}],"name":"applyDestChainConfigUpdates","outputs":[],"stateMutability":"nonpayable","type":"function"},{"inputs":[{"internalType":"uint64","name":"destChainSelector","type":"uint64"},{"components":[{"internalType":"bytes","name":"receiver","type":"bytes"},{"internalType":"bytes","name":"data","type":"bytes"},{"components":[{"internalType":"address","name":"token","type":"address"},{"internalType":"uint256","name":"amount","type":"uint256"}],"internalType":"struct Client.EVMTokenAmount[]","name":"tokenAmounts","type":"tuple[]"},{"internalType":"address","name":"feeToken","type":"address"},{"internalType":"bytes","name":"extraArgs","type":"bytes"}],"internalType":"struct Client.EVM2AnyMessage","name":"message","type":"tuple"},{"internalType":"uint256","name":"feeTokenAmount","type":"uint256"},{"internalType":"address","name":"originalSender","type":"address"}],"name":"forwardFromRouter","outputs":[{"internalType