    for (uint256 i = 0; i < requiredCCVs.length; ++i) {
      address poolCCV = requiredCCVs[i];
      if (poolCCV == address(0)) {
        includeDefaults = true;
        continue;
      }
      resolvedCCVs[writeIndex++] = poolCCV;
    }

    if (includeDefaults) {
      for (uint256 i = 0; i < defaultCCVs.length; ++i) {
