pragma solidity ^0.8.4;

import {Internal} from "../libraries/Internal.sol";

/// @notice This interface contains the only RMN-related functions that might be used on-chain by other CCIP contracts.
interface IRMNRemote {
  /// @notice signature components from RMN nodes.
  struct Signature {
    bytes32 r;
    bytes32 s;
  }

  /// @notice Verifies signatures of RMN nodes, on dest lane updates as provided in the CommitReport.
  /// @param offRampAddress is not inferred by msg.sender, in case the call is made through RMNProxy.
  /// @param merkleRoots must be well formed, and is a representation of the CommitReport received from the oracles.
  /// @param signatures rmnNodes ECDSA sigs, only r & s, must be sorted in ascending order by signer address.
  /// @dev Will revert if verification fails.
  function verify(
    address offRampAddress,
    Internal.MerkleRoot[] memory merkleRoots,
    Signature[] memory signatures
  ) external view;

  /// @notice gets the current set of cursed subjects.
  /// @return subjects the list of cursed subjects.
  function getCursedSubjects() external view returns (bytes16[] memory subjects);

  /// @notice If there is an active global or legacy curse, this function returns true.
  /// @return bool true if there is an active global curse.
  function isCursed() external view returns (bool);

  /// @notice If there is an active global curse, or an active curse for `subject`, this function returns true.
  /// @param subject To check whether a particular chain is cursed, set to bytes16(uint128(chainSelector)).
  /// @return bool true if the provided subject is cured *or* if there is an active global curse.
  function isCursed(
    bytes16 subject
  ) external view returns (bool);
}
"},"contracts/interfaces/ICrossChainVerifierResolver.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.24;

/// @notice Resolves and returns the appropriate verifier contract for the given outbound / inbound traffic.
interface ICrossChainVerifierResolver {
  /// @notice Returns the appropriate verifier contract based on the given verifierResults.
  /// @dev The OffRamp is responsible for calling this function using the verifierResults it receives from the executor.
  /// If the verifier specified by the executor is actually a resolver, the OffRamp will call this function to get the actual verifier contract.
  /// Verifiers can build resolvers that process the verifierResults in accordance with how their verifier forms verifierResults. For example, their verifier may
  /// prefix the verifierResults with a version identifier, which the resolver can parse to determine the correct verifier contract.
  /// @param verifierResults The verifierResults formed by the verifier.
  /// @return verifierAddress The address of the verifier contract.
  function getInboundImplementation(
    bytes calldata verifierResults
  ) external view returns (address);

  /// @notice Returns the appropriate verifier contract based on the given destChainSelector.
  /// @dev The OnRamp is responsible for calling this function using the destChainSelector specified by the sender.
  /// If the verifier specified by the sender is actually a resolver, the OnRamp will call this function to get the actual verifier contract.
  /// For example, resolvers can maintain a simple mapping of destChainSelector to verifier contract address.
  /// @param destChainSelector The destChainSelector for a message.
  /// @param extraArgs Extra arguments that can be used by the resolver to determine the correct verifier contract.
  /// @return verifierAddress The address of the verifier contract.
  function getOutboundImplementation(
    uint64 destChainSelector,
    bytes memory extraArgs
  ) external view returns (address);
}
"},"contracts/interfaces/IRouter.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {Client} from "../libraries/Client.sol";

interface IRouter {
  error OnlyOffRamp();

  /// @notice Route the message to its intended receiver contract.
  /// @param message Client.Any2EVMMessage struct.
  /// @param gasForCallExactCheck of params for exec.
  /// @param gasLimit set of params for exec.
  /// @param receiver set of params for exec.
  /// @dev if the receiver is a contracts that signals support for CCIP execution through EIP-165.
  /// the contract is called. If not, only tokens are transferred.
  /// @return success A boolean value indicating whether the ccip message was received without errors.
  /// @return retBytes A bytes array containing return data form CCIP receiver.
  /// @return gasUsed the gas used by the external customer call. Does not include any overhead.
  function routeMessage(
    Client.Any2EVMMessage calldata message,
    uint16 gasForCallExactCheck,
    uint256 gasLimit,
    address receiver
  ) external returns (bool success, bytes memory retBytes, uint256 gasUsed);

  /// @notice Returns the configured onRamp for a specific destination chain.
  /// @param destChainSelector The destination chain Id to get the onRamp for.
  /// @return onRampAddress The address of the onRamp.
  function getOnRamp(
    uint64 destChainSelector
  ) external view returns (address onRampAddress);

  /// @notice Return true if the given offRamp is a configured offRamp for the given source chain.
  /// @param sourceChainSelector The source chain selector to check.
  /// @param offRamp The address of the offRamp to check.
  function isOffRamp(
    uint64 sourceChainSelector,
    address offRamp
  ) external view returns (bool isOffRamp);
}
"},"node_modules/@openzeppelin/contracts-5.3.0/utils/math/SafeCast.sol":{"content":"// SPDX-License-Identifier: MIT
